/*
 * thumbFor(src) — resolves a full-size asset URL to its optimized WebP
 * thumbnail (e.g. "poster.png" → "poster.thumb.webp") when one exists in
 * src/assets, otherwise returns the original URL unchanged.
 *
 * Thumbnails are generated by scripts/optimize-images.mjs (sharp). Until
 * they exist, every call safely falls back to the original image, so the
 * build never breaks. Full-size sources stay in the data untouched and
 * are still used by the lightbox.
 */

// Eagerly map every asset URL Vite knows about (module path -> resolved URL).
const modules = import.meta.glob("../assets/**/*.{png,jpg,jpeg,webp}", {
  eager: true,
  query: "?url",
  import: "default",
});

// resolved URL -> module path, so we can look up a sibling thumbnail path.
const pathByUrl = new Map(Object.entries(modules).map(([path, url]) => [url, path]));
const urlByPath = modules;

const EXT_RE = /\.(png|jpe?g|webp)$/i;

export function thumbFor(src) {
  if (typeof src !== "string") return src;
  const path = pathByUrl.get(src);
  if (!path) return src; // remote URL (Unsplash) or unknown asset
  const thumbPath = path.replace(EXT_RE, ".thumb.webp");
  const thumbUrl = urlByPath[thumbPath];
  return thumbUrl ?? src;
}
